server {
    listen 6700 default_server;
    server_name _;

    location / {
        root /usr/share/nginx/html;
        index index.html;
    }
}
ANTRIEB_EOF
cat > /usr/share/nginx/html/index.html <<'ANTRIEB_EOF'
<!doctype html>
<html><body><h1>Nginx is serving on port 6700</h1></body></html>
ANTRIEB_EOF
